    section { padding: 80px 0; }
    .section-label { display: inline-flex; align-items: center; gap: 6px; background: rgba(24,104,219,0.08); color: var(--primary); font-weight: 700; font-size: 0.78rem; padding: 5px 12px; border-radius: 100px; margin-bottom: 16px; text-transform: uppercase; letter-spacing: 0.05em; border: 1px solid rgba(24,104,219,0.15); }
    .btn-accent { padding: 14px 28px; border-radius: var(--radius-sm); font-weight: 700; font-size: 1rem; background: var(--accent); color: #fff; transition: all 150ms; box-shadow: 0 2px 8px rgba(255,97,61,0.3); display: inline-flex; align-items: center; gap: 8px; }
