    .btn-secondary:hover { border-color: var(--primary); color: var(--primary); transform: translateY(-1px); }

    /* HERO */
    .hero { background: linear-gradient(135deg, #0d1829 0%, #1a2744 50%, #0f2d4a 100%); padding: 96px 0 80px; text-align: center; position: relative; overflow: hidden; }
    .hero::before { content: ''; position: absolute; top: -80px; left: 50%; transform: translateX(-50%); width: 800px; height: 500px; background: radial-gradient(ellipse, rgba(24,104,219,0.2) 0%, transparent 70%); }
