    .btn-white-hero:hover { transform: translateY(-1px); box-shadow: 0 6px 20px rgba(0,0,0,0.15); }
    .btn-outline-hero { padding: 14px 28px; border-radius: var(--radius-sm); font-weight: 700; font-size: 1rem; background: transparent; color: #fff; border: 2px solid rgba(255,255,255,0.3); transition: all 150ms; display: inline-flex; align-items: center; gap: 8px; }
    .btn-outline-hero:hover { border-color: #fff; background: rgba(255,255,255,0.05); }

    /* LOGO BAR */
    .logo-bar { padding: 40px 0; border-bottom: 1px solid var(--border); background: var(--bg-light); }
    .logo-bar p { text-align: center; font-size: 0.85rem; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 24px; }
    .logo-row { display: flex; align-items: center; justify-content: center; gap: 40px; flex-wrap: wrap; }
    .logo-row span { font-size: 1.05rem; font-weight: 700; color: #9CA3AF; }

    /* ASYNC BENEFITS */
    .async-benefits { background: var(--bg); }
    .async-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
    .async-benefits-list { display: flex; flex-direction: column; gap: 28px; margin-top: 28px; }
    .benefit-item { display: flex; gap: 16px; }
    .benefit-icon { width: 48px; height: 48px; border-radius: 12px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
    .benefit-item h3 { margin-bottom: 6px; }
    .async-visual { background: linear-gradient(135deg, #1868DB 0%, #0f4fa0 100%); border-radius: 20px; padding: 36px; box-shadow: var(--shadow-lg); }
    .async-stat { margin-bottom: 24px; padding-bottom: 24px; border-bottom: 1px solid rgba(255,255,255,0.12); }
    .async-stat:last-child { margin-bottom: 0; padding-bottom: 0; border-bottom: none; }
    .async-stat .num { font-size: 2.5rem; font-weight: 800; color: #fff; line-height: 1; }
    .async-stat .desc { color: rgba(255,255,255,0.75); font-size: 0.9rem; margin-top: 6px; }

    /* COMMUNITY VISIBILITY */
    .community { background: var(--bg-light); }
