    .community-header p { margin-top: 14px; font-size: 1.05rem; }
    .community-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
    .community-card { background: var(--bg); border: 1px solid var(--border); border-radius: var(--radius); padding: 32px 24px; transition: all 150ms; }
    .community-card:hover { box-shadow: var(--shadow); transform: translateY(-2px); }
    .community-card-icon { width: 52px; height: 52px; border-radius: 14px; margin-bottom: 20px; display: flex; align-items: center; justify-content: center; }
    .community-card h3 { margin-bottom: 10px; }

    /* TESTIMONIAL QUOTE */
    .testimonial-quote { background: var(--text-dark); padding: 80px 0; }
    .quote-inner { max-width: 760px; margin: 0 auto; text-align: center; }
    .quote-mark { font-size: 6rem; line-height: 1; color: var(--primary); font-weight: 800; margin-bottom: -20px; display: block; }
    .quote-text { font-size: clamp(1.15rem, 2vw, 1.5rem); font-weight: 600; color: #fff; line-height: 1.6; font-style: italic; margin-bottom: 28px; }
    .quote-author { display: flex; align-items: center; justify-content: center; gap: 14px; }
    .quote-avatar { width: 52px; height: 52px; border-radius: 50%; background: var(--primary); display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 1rem; color: #fff; }
    .quote-author-text strong { display: block; color: #fff; font-size: 1rem; }
    .quote-author-text span { color: rgba(255,255,255,0.6); font-size: 0.88rem; }

    /* SECURITY */
    .security-section { background: var(--bg); }
    .security-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
    .security-list { display: flex; flex-direction: column; gap: 14px; margin: 24px 0 32px; }
    .security-item { display: flex; align-items: flex-start; gap: 12px; }
    .check-circle { width: 22px; height: 22px; border-radius: 50%; background: rgba(16,185,129,0.12); display: flex; align-items: center; justify-content: center; flex-shrink: 0; margin-top: 2px; }
    .check-circle svg { color: #10B981; }
    .security-badges { display: flex; gap: 10px; flex-wrap: wrap; }
    .badge { background: var(--bg-light); border: 1px solid var(--border); font-size: 0.8rem; font-weight: 600; color: var(--text-body); padding: 6px 14px; border-radius: 6px; }
    .security-visual-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
