    /* USE CASES GRID */
    .use-cases { background: var(--bg-light); }
    .use-cases-header { text-align: center; max-width: 560px; margin: 0 auto 48px; }
    .use-cases-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
    .uc-card { background: var(--bg); border: 1px solid var(--border); border-radius: var(--radius); padding: 28px 22px; transition: all 150ms; }
