    .pricing-preview-cards { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-bottom: 32px; }
    .pp-card { background: var(--bg-light); border: 1px solid var(--border); border-radius: var(--radius); padding: 28px 22px; transition: all 150ms; }
    .pp-card.featured { background: var(--primary); border-color: var(--primary); transform: scale(1.03); }
    .pp-card.featured h3, .pp-card.featured .price, .pp-card.featured p { color: #fff; }
    .pp-card h3 { font-size: 1rem; margin-bottom: 6px; color: var(--text-body); font-weight: 700; }
