    .btn-outline-white { padding: 14px 28px; border-radius: var(--radius-sm); font-weight: 700; background: transparent; border: 2px solid rgba(255,255,255,0.3); color: #fff; font-size: 1rem; transition: all 150ms; }
    .btn-outline-white:hover { border-color: #fff; }
