    .footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 24px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px; }
    .footer-bottom span { font-size: 0.82rem; }
    .footer-bottom-links { display: flex; gap: 20px; }
    .footer-bottom-links a { font-size: 0.82rem; color: rgba(255,255,255,0.5); transition: color 150ms; }
    .footer-bottom-links a:hover { color: #fff; }

    @media (max-width: 1024px) {
      .async-grid, .security-inner { grid-template-columns: 1fr; }
