<script>
  // BILLING TOGGLE
  const billingToggle = document.getElementById('billing-toggle-input');
  const monthlyLabel = document.getElementById('monthly-label');
  const annualLabel = document.getElementById('annual-label');

  billingToggle.addEventListener('change', function() {
    const isAnnual = this.checked;
    this.setAttribute('aria-checked', isAnnual);

    monthlyLabel.classList.toggle('active', !isAnnual);
    annualLabel.classList.toggle('active', isAnnual);

    // Update plan card prices
    document.querySelectorAll('.price-amount[data-annual]').forEach(el => {
      el.textContent = isAnnual ? el.dataset.annual : el.dataset.monthly;
    });
    document.querySelectorAll('.price-period[data-annual]').forEach(el => {
      el.textContent = isAnnual ? el.dataset.annual : el.dataset.monthly;
    });
    // Update comparison table price cells
    document.querySelectorAll('.price-cell').forEach(el => {
      const base = isAnnual ? el.dataset.annual : el.dataset.monthly;
      el.innerHTML = base + '<span style="font-size:0.75rem;font-weight:500;">/mo</span>';
    });
  });
  // Init active state
  monthlyLabel.classList.add('active');

  // TEAM SIZE SLIDER
  const slider = document.getElementById('team-slider');
  const display = document.getElementById('team-size-display');
  slider.addEventListener('input', function() {
    const val = parseInt(this.value);
    display.textContent = val === 200 ? '200+ members' : `${val} member${val !== 1 ? 's' : ''}`;
    this.setAttribute('aria-valuenow', val);
  });

  // FAQ ACCORDION
  function toggleFaq(btn) {
    const expanded = btn.getAttribute('aria-expanded') === 'true';
    const answerId = btn.getAttribute('aria-controls');
    const answer = document.getElementById(answerId);

    // Close all others
    document.querySelectorAll('.faq-question[aria-expanded="true"]').forEach(other => {
      if (other !== btn) {
        other.setAttribute('aria-expanded', 'false');
        const otherId = other.getAttribute('aria-controls');
        document.getElementById(otherId).classList.remove('open');
      }
    });

    btn.setAttribute('aria-expanded', String(!expanded));
    answer.classList.toggle('open', !expanded);
  }

  // EXPAND FEATURES (plan cards)
  function toggleFeatures(btn) {
    const card = btn.closest('.plan-card');
    const extra = card.querySelector('.extra-features');
    const expanded = btn.getAttribute('aria-expanded') === 'true';
    btn.setAttribute('aria-expanded', String(!expanded));
    extra.classList.toggle('open', !expanded);
    btn.querySelector('span') && (btn.querySelector('span').textContent = !expanded ? 'Hide features' : 'See all features');
    const textNode = btn.childNodes[0];
    if (textNode && textNode.nodeType === 3) {
      textNode.textContent = !expanded ? 'Hide features ' : 'See all features ';
    }
  }
</script>
